	t.Helper()
	rec := doRequest(t, router, http.MethodGet, target, nil)
	if rec.Code != http.StatusOK {
		t.Fatalf("overview %s: status %d body %s", target, rec.Code, rec.Body.String())
	}
	return rec.Code, decodeBody(t, rec)
}

